import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"规范与多语言","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/spec.md","filePath":"appendix/spec.md","lastUpdated":1795105677000}`),a={name:`appendix/spec.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="规范与多语言" tabindex="-1">规范与多语言 <a class="header-anchor" href="#规范与多语言" aria-label="Permalink to “规范与多语言”">​</a></h1><p>XiHan Framework 的本体不是 .NET 代码，而是一份语言中立的规范：XiHan Spec。.NET 实现是它的参考实现，Go SDK 是第二个实现，其他语言按同一份规范实现并通过同一套一致性测试。这一页讲规范怎样组织、哪些内容是规范性的、一致性测试怎样工作、规范怎样定版与变更，以及各语言 SDK 的现状。要写插件或另一种语言的 SDK 的读者需要读它；只用 .NET 的读者了解即可。</p><h2 id="为什么要有规范" tabindex="-1">为什么要有规范 <a class="header-anchor" href="#为什么要有规范" aria-label="Permalink to “为什么要有规范”">​</a></h2><p>「同一个名字各语言都能用」这件事，只有两条路：要么每种语言各写一个风格相似的框架，然后在文档里宣称它们是一家；要么先写下语言中立的语义，再让每种实现去通过同一套测试。前者做出来的东西经不起细看，后者才是 OpenTelemetry、MCP、CloudEvents 走通的路。我选了后者。</p><p>规范还解决一个 .NET 内部的问题：公开契约先写进规范，再写架构决策记录，再写代码与一致性向量。没有 RFC 的公开 API 变更不合并。这条流程让「随手加一个公开方法」变得不可能，也让每个设计决定都有据可查。</p><h2 id="规范仓库" tabindex="-1">规范仓库 <a class="header-anchor" href="#规范仓库" aria-label="Permalink to “规范仓库”">​</a></h2><p>规范在独立仓库 <a href="https://github.com/XiHanFun/framework-spec" target="_blank" rel="noreferrer">XiHanFun/framework-spec</a>，文档都用中文写。它涵盖原语语义与线上编码、清单 Schema、调用上下文与传播、管道阶段与排序、进程外插件协议 <code>xihan.plugin.v1</code> 与 Wasm 载体、协议映射、应用清单与打包，以及数据驱动的一致性向量和黑盒运行器。目录结构：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spec/</span></span>
<span class="line"><span>├─ rfcs/           提案：先 RFC，再 ADR，再实现</span></span>
<span class="line"><span>├─ conventions/    规范性：术语表、包 ID、能力 ID、操作 ID、错误码、Baggage 键、批量优先</span></span>
<span class="line"><span>├─ manifest/       规范性：xihan.manifest.json 的 JSON Schema</span></span>
<span class="line"><span>├─ plugin/         规范性：插件协议 plugin.proto 与握手、生命周期、调用文本；Wasm 载体 wasm.md</span></span>
<span class="line"><span>├─ protocol/       规范性：HTTP、gRPC、MCP、CloudEvents、命令行的映射</span></span>
<span class="line"><span>├─ packaging/      规范性：应用清单 xihan.app.json 与 xihan pack 的产物映射</span></span>
<span class="line"><span>├─ provider/       规范性：远程 Provider 的通用规则与各能力的操作集（caching.distributed）</span></span>
<span class="line"><span>├─ migration/      规范性：xihan migrate 的通用约定（命令、标记、报告格式）与各来源版本的规则集</span></span>
<span class="line"><span>└─ conformance/    一致性档表（profiles.json）、向量（vectors/）与黑盒运行器（Go 模块）</span></span></code></pre></div><h3 id="引用规范" tabindex="-1">引用规范 <a class="header-anchor" href="#引用规范" aria-label="Permalink to “引用规范”">​</a></h3><p>规范文件按相对路径互相链接，整个仓库可以作为 git submodule 放进实现仓库：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/XiHanFun/framework-spec.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spec</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span></span></code></pre></div><p>XiHan.Framework 引用到 <code>framework/spec</code>，各语言 SDK 引用到 <code>spec</code>。<code>plugin/plugin.proto</code> 由各语言用自己的 protobuf 工具链生成代码。</p><h2 id="规范性与信息性" tabindex="-1">规范性与信息性 <a class="header-anchor" href="#规范性与信息性" aria-label="Permalink to “规范性与信息性”">​</a></h2><p>不是所有东西都要各语言一致。规范把内容分成两类：</p><table tabindex="0"><thead><tr><th>规范性（认领了所属档的实现必须一致）</th><th>信息性（各语言自选）</th></tr></thead><tbody><tr><td>原语语义与线上编码（<code>Result</code>、<code>Error</code>、<code>Maybe</code> 的 JSON 形态）</td><td>内部 API 形态</td></tr><tr><td>清单 Schema</td><td>包管理与目录布局</td></tr><tr><td>上下文传播键与载体</td><td>日志实现</td></tr><tr><td>管道阶段名与排序规则</td><td>具体中间件</td></tr><tr><td>插件协议</td><td>隔离机制</td></tr><tr><td>协议映射（路由推导、错误信封）</td><td>服务器实现</td></tr><tr><td>术语表、错误码、能力 ID、操作 ID、包 ID 命名</td><td>代码风格</td></tr><tr><td>批量优先：集合入参、原生批量、部分失败语义（<code>conventions/batch-first.md</code>）</td><td>批次大小</td></tr></tbody></table><p>举例说，<code>orders.create</code> 在任何语言的实现里都推导为 <code>POST /orders</code>，失败时都返回 RFC 9457 的 Problem Details，错误码都是 <code>&lt;领域大写&gt;_&lt;KIND&gt;_&lt;三位序号&gt;</code>；但 Go 用 <code>context.Context</code> 传递取消、.NET 用 <code>CancellationToken</code>，这是各语言自己的事。</p><p>规范性内容又按一致性档划分（RFC-0024）。一个实现认领若干档，只对认领的档负责；档表是规范仓库的 <a href="https://github.com/XiHanFun/framework-spec/blob/main/conformance/profiles.json" target="_blank" rel="noreferrer"><code>conformance/profiles.json</code></a>，每个 RFC 的状态行写着它属于哪些档：</p><table tabindex="0"><thead><tr><th>档</th><th>内容</th><th>谁认领</th></tr></thead><tbody><tr><td><code>core</code></td><td>所有实现都认领：原语与线上编码、清单读写、调用上下文、管道阶段与排序、消息模板、操作契约与载荷、命名约定</td><td>所有实现</td></tr><tr><td><code>plugin</code></td><td>用本实现写进程外插件：握手、生命周期、调用与回调的插件一侧，并通过黑盒运行器</td><td>六个 SDK</td></tr><tr><td><code>host</code></td><td>宿主：能力求解、进程外插件宿主、协议映射、应用清单与打包、版本迁移</td><td>.NET</td></tr><tr><td><code>wasm</code></td><td>Wasm 插件 ABI（Experimental）</td><td>.NET</td></tr><tr><td>子系统档</td><td>一个子系统 RFC 一档，按能力 ID 前缀命名：<code>persistence</code>、<code>caching</code>、<code>multitenancy</code>、<code>security</code>、<code>messaging</code>、<code>localization</code>、<code>objectstorage</code>、<code>scheduling</code>、<code>configuration</code>、<code>auditing</code>、<code>workflow</code>、<code>ai</code>、<code>observability</code></td><td>.NET</td></tr><tr><td><code>provider:&lt;操作集&gt;</code></td><td>远程 Provider 的操作集，目前只有 <code>provider:caching.distributed@1</code></td><td>.NET（适配器）、Go（插件）</td></tr></tbody></table><h2 id="一致性测试" tabindex="-1">一致性测试 <a class="header-anchor" href="#一致性测试" aria-label="Permalink to “一致性测试”">​</a></h2><p>一致性有两层：</p><table tabindex="0"><thead><tr><th>层</th><th>位置</th><th>形式</th><th>谁用</th></tr></thead><tbody><tr><td>数据驱动向量</td><td><code>conformance/vectors/</code></td><td>JSON 文件，按主题分目录（<code>primitives/</code>、<code>manifest/</code>、<code>pipeline/</code>、<code>operations/</code>、<code>plugin/</code>、<code>security/</code>、<code>provider/</code>）：<code>Result</code> 与 <code>Error</code> 编码、清单校验、版本解析、管道排序、上下文传播、包 ID 与能力 ID 文法，以及插件的握手行、回调端点、截止时间、回调状态的映射与错误的读入</td><td>各语言 SDK 的单元测试直接读取这些文件；Go 可以 <code>go get github.com/xihanfun/framework-spec/conformance</code> 后经内嵌的 <code>conformance.Vectors</code> 读取</td></tr><tr><td>黑盒运行器</td><td><code>conformance/cmd/xihan-conformance</code></td><td>语言中立，以宿主身份启动任意语言写的进程外插件；运行器本身用 Go 写成</td><td>插件作者、远程 Provider 作者</td></tr></tbody></table><p>安装运行器：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/xihanfun/framework-spec/conformance/cmd/xihan-conformance@latest</span></span></code></pre></div><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>xihan-conformance plugin --dir &lt;插件目录&gt;</code></td><td>按 <code>plugin/handshake.md</code>、<code>lifecycle.md</code>、<code>invocation.md</code> 核对握手行与版本协商、无共同版本时拒绝、会话令牌（含两个令牌值）、清单一致性、Configure / Start / Health / WatchHealth / Stop 与宽限内退出、调用次序不对时 <code>FailedPrecondition</code>、未知操作 <code>Unimplemented</code>、声明的操作都返回 <code>status</code>、<code>Start</code> 之前的调用与投递报 <code>plugins.process.unavailable</code>、订阅投递确认、没人订阅或方式未知的投递报 <code>plugins.event.unsubscribed</code> 与 <code>InvalidArgument</code>、<code>InvokeStream</code> 的第一帧、配置节不是 JSON 对象时进入 <code>Failed</code>、<code>Start</code> 之前的 <code>Stop</code> 应答后退出、stdin 关闭即退出；每个插件都以两项的 <code>XIHAN_PLUGIN_HOST_ADDRESS</code> 启动</td></tr><tr><td><code>xihan-conformance vectors</code></td><td>校验向量文件本身</td></tr></tbody></table><p>各向量文件的内容、规则包、运行器的用例与选项见规范仓库的 <a href="https://github.com/XiHanFun/framework-spec/blob/main/conformance/README.md" target="_blank" rel="noreferrer">conformance/README.md</a>。</p><p>.NET 侧另有每个子系统的 <code>&lt;领域&gt;.Conformance</code> 包，是 xUnit 套件：默认实现与 Provider 都要通过，远程 Provider 跑同一套。用法见<a href="/testing/conformance">一致性套件与门禁</a>。</p><h2 id="规范的版本" tabindex="-1">规范的版本 <a class="header-anchor" href="#规范的版本" aria-label="Permalink to “规范的版本”">​</a></h2><p>规范以独立的语义化版本 <code>vX.Y.Z</code> 打标签，与框架的版本线分开（RFC-0024）；Go 的一致性模块在同一提交另打 <code>conformance/vX.Y.Z</code>：</p><ul><li>PATCH 不改规范性内容。</li><li>MINOR 只增，或把以前不作规定的行为写死，但不能让按较早 MINOR 实现的对端互通失败。</li><li>MAJOR 改已经写明的行为、删除内容或线上不兼容；<code>v2</code> 与 <code>v1</code> 并存，对应原语层的冻结规则（RFC-0001）。</li></ul><p>大版本与线上的数字一致：<code>FrameworkInfo.SpecVersion</code>、清单的 <code>primitives</code> 都是 <code>1</code>。<code>v1.0.0</code> 之前打 <code>v1.0.0-rc.N</code>，rc 之间允许任何改动；<code>v1.0.0</code> 与 XiHan.Framework 的 5.0.0 正式版一起打。改动记在规范仓库的 <a href="https://github.com/XiHanFun/framework-spec/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a>。</p><p>规范的日常提交在 <code>dev</code>，<code>main</code> 由 <code>dev</code> 快进，标签打在 <code>main</code> 上。实现的日常分支可以指向规范已推送的任意提交；发版时子模块必须正好在规范标签上，正式版只钉正式版标签。</p><h2 id="各语言-sdk" tabindex="-1">各语言 SDK <a class="header-anchor" href="#各语言-sdk" aria-label="Permalink to “各语言 SDK”">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>包名</th><th>仓库</th><th>认领的档</th><th>成熟度</th></tr></thead><tbody><tr><td>.NET</td><td><code>XiHan.Framework.*</code></td><td><a href="https://github.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHan.Framework</a></td><td><code>plugin</code> 之外的全部档：<code>core</code>、<code>host</code>、<code>wasm</code>、全部子系统档、<code>provider:caching.distributed@1</code>（适配器）</td><td>Reference</td></tr><tr><td><a href="/sdks/go">Go</a></td><td><code>github.com/xihanfun/framework-sdk-go</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-go" target="_blank" rel="noreferrer">framework-sdk-go</a></td><td><code>core</code>、<code>plugin</code>、<code>provider:caching.distributed@1</code>（插件）</td><td>Experimental</td></tr><tr><td><a href="/sdks/typescript">TypeScript</a></td><td>npm <code>xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-typescript" target="_blank" rel="noreferrer">framework-sdk-typescript</a></td><td><code>core</code>、<code>plugin</code></td><td>Experimental</td></tr><tr><td><a href="/sdks/rust">Rust</a></td><td>crate <code>xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-rust" target="_blank" rel="noreferrer">framework-sdk-rust</a></td><td><code>core</code>、<code>plugin</code></td><td>Experimental</td></tr><tr><td><a href="/sdks/java">Java</a></td><td><code>com.xihanfun:xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-java" target="_blank" rel="noreferrer">framework-sdk-java</a></td><td><code>core</code>、<code>plugin</code></td><td>Experimental</td></tr><tr><td><a href="/sdks/python">Python</a></td><td><code>xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-python" target="_blank" rel="noreferrer">framework-sdk-python</a></td><td><code>core</code>、<code>plugin</code></td><td>Experimental</td></tr><tr><td><a href="/sdks/php">PHP</a></td><td><code>xihanfun/xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-php" target="_blank" rel="noreferrer">framework-sdk-php</a></td><td><code>core</code>、<code>plugin</code></td><td>Experimental</td></tr></tbody></table><p>七个实现在认领的档里都没有缺口。六个 SDK 都提供原语、清单、调用上下文、管道、操作契约与进程外插件运行时，Go 还用于远程 Provider；它们还是 Experimental，因为还没有钉在规范标签上的发布版。</p><p>成熟度按认领的档判定（RFC-0024）：</p><ul><li>Reference：.NET。</li><li>Stable：认领的档里每个向量都回放并通过，运行器全部通过，且有钉在规范正式版标签上的发布版。</li><li>Experimental：有没回放的向量（缺口），或还没有这样的发布版。</li><li>Community：社区维护。</li></ul><p>SDK 仓库按 <code>framework-sdk-&lt;语言&gt;</code> 命名（ADR-0010）。除 .NET 参考实现外，每种语言的 SDK 只有一个包，包名都是 <code>xihan-framework</code>，需要写所有者的生态用 <code>xihanfun</code>；Go 的模块路径必须是仓库地址，所以跟着仓库名。</p><p>各语言的领域词与术语表一致，只换大小写风格。</p><p>为什么 Go 先行：它离 C# 最远，能证明规范不是 .NET 形状的；同时它适合承载进程外插件、黑盒运行器和将来的 Kubernetes Operator。Go SDK 已经做到的事：用 Go 写的插件在 .NET 宿主里服务一个操作，崩溃时宿主降级而不退出；用 Go 实现的分布式缓存经远程 Provider 适配器通过 .NET 的缓存一致性套件。示例见 <code>framework/samples/EchoGoPlugin</code> 与 <code>CacheGoPlugin</code>，写法见<a href="/plugins/out-of-process">进程外插件</a>。</p><h2 id="变更流程" tabindex="-1">变更流程 <a class="header-anchor" href="#变更流程" aria-label="Permalink to “变更流程”">​</a></h2><p>公开契约的变更按固定顺序走 RFC 流程：</p><ol><li>在 <code>rfcs/</code> 新建 <code>NNNN-&lt;slug&gt;.md</code>，状态为 <code>草案</code>。</li><li>评审通过后写架构决策记录（XiHan.Framework 的 <code>plans/adr/</code>），RFC 状态改为 <code>已采纳</code>，正文并入对应的规范性目录。</li><li>实现与一致性向量随 RFC 一起合并；没有 RFC 的公开契约变更不合并。</li><li>改动规范性内容的提交在 <code>CHANGELOG.md</code> 的「未发布」一节记一条，标明 PATCH、MINOR 或 MAJOR 与 ADR（RFC-0024）；新的规范文件与向量要写进档表。</li></ol><p>新增术语表条目同样走 RFC。错误码、能力 ID、Baggage 键、操作 ID 一经发布不改。提交前的门禁与写法约定见规范仓库的 <a href="https://github.com/XiHanFun/framework-spec/blob/main/AGENTS.md" target="_blank" rel="noreferrer">AGENTS.md</a>。</p><h2 id="已采纳的-rfc" tabindex="-1">已采纳的 RFC <a class="header-anchor" href="#已采纳的-rfc" aria-label="Permalink to “已采纳的 RFC”">​</a></h2><p>参考实现的路径相对 XiHan.Framework 的 <code>framework/src</code>。</p><table tabindex="0"><thead><tr><th>RFC</th><th>主题</th><th>参考实现与修订</th></tr></thead><tbody><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0001-primitives.md" target="_blank" rel="noreferrer">0001</a></td><td>原语层</td><td>参考实现 <code>XiHan.Framework.Primitives</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0002-manifest.md" target="_blank" rel="noreferrer">0002</a></td><td>清单</td><td>参考实现 <code>Kernel.Capabilities</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0003-invocation-context.md" target="_blank" rel="noreferrer">0003</a></td><td>调用上下文与传播</td><td>载体映射随协议适配器实现</td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0004-pipeline-stages.md" target="_blank" rel="noreferrer">0004</a></td><td>管道阶段与排序</td><td>参考实现 <code>Kernel.Pipeline</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0005-persistence.md" target="_blank" rel="noreferrer">0005</a></td><td>领域协议与持久化</td><td>参考实现 <code>Domain</code>、<code>Persistence.Abstractions</code>，套件 <code>Persistence.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0006-caching.md" target="_blank" rel="noreferrer">0006</a></td><td>缓存、分布式锁与幂等</td><td>参考实现 <code>Caching.Abstractions</code>、<code>Caching.InMemory</code>、<code>Caching.Redis</code>、<code>Caching.Hybrid</code>，套件 <code>Caching.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0007-multitenancy.md" target="_blank" rel="noreferrer">0007</a></td><td>多租户</td><td>参考实现 <code>MultiTenancy.Abstractions</code>、<code>MultiTenancy.InMemory</code>，套件 <code>MultiTenancy.Conformance</code>；Provider <code>MultiTenancy.Database</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0008-security.md" target="_blank" rel="noreferrer">0008</a></td><td>认证与授权</td><td>参考实现 <code>Security.Abstractions</code>、<code>Security.InMemory</code>、<code>Security.Jwt</code>、<code>Security.OpenIdConnect</code>，套件 <code>Security.Conformance</code>；Provider <code>Security.Database</code>、<code>Security.Ip2Region</code>（IP 归属地）</td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0009-messaging.md" target="_blank" rel="noreferrer">0009</a></td><td>消息、CloudEvents 信封与发件箱</td><td>参考实现 <code>Messaging.Abstractions</code>、<code>Messaging.InMemory</code>、<code>Messaging.RabbitMQ</code>、<code>Messaging.Kafka</code>、<code>Messaging.Redis</code>，套件 <code>Messaging.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0010-localization.md" target="_blank" rel="noreferrer">0010</a></td><td>本地化：默认英文与 10 种内置区域</td><td>参考实现 <code>Localization.Abstractions</code>、<code>Localization.InMemory</code>；Provider <code>Localization.Database</code>，套件 <code>Localization.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0011-operations.md" target="_blank" rel="noreferrer">0011</a></td><td>操作契约与 XGI 消息</td><td>参考实现 <code>Kernel.Operations</code>，协议适配器在 <code>Protocols.*</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0012-objectstorage.md" target="_blank" rel="noreferrer">0012</a></td><td>对象存储</td><td>参考实现 <code>ObjectStorage.Abstractions</code>、<code>ObjectStorage.FileSystem</code>、<code>ObjectStorage.S3</code>，套件 <code>ObjectStorage.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0013-scheduling.md" target="_blank" rel="noreferrer">0013</a></td><td>调度与领导选举</td><td>2026-10-26 修订：作业存储、动态作业、多触发器、misfire、暂停、历史、集群分发；参考实现 <code>Scheduling.Abstractions</code>、<code>Scheduling.InMemory</code>、<code>Scheduling.Database</code>，套件 <code>Scheduling.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0014-configuration.md" target="_blank" rel="noreferrer">0014</a></td><td>远程配置与密钥</td><td>参考实现 <code>Configuration.Abstractions</code>、<code>Configuration.Nacos</code>，套件 <code>Configuration.Conformance</code>；默认实现是 .NET 原生文件与环境变量，无包</td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0015-auditing.md" target="_blank" rel="noreferrer">0015</a></td><td>审计</td><td>参考实现 <code>Auditing.Abstractions</code>、<code>Auditing.InMemory</code>，套件 <code>Auditing.Conformance</code>；Provider <code>Auditing.Database</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0016-packaging.md" target="_blank" rel="noreferrer">0016</a></td><td>应用清单与打包</td><td>参考实现 <code>Cli</code> 的 <code>xihan pack</code>；规范 <code>packaging/</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0017-plugin-protocol.md" target="_blank" rel="noreferrer">0017</a></td><td>进程外插件协议 <code>xihan.plugin.v1</code></td><td>规范 <code>plugin/</code>；参考实现 <code>Plugins.OutOfProcess</code>（协议代码在 <code>Plugins.Protocol</code>），套件 <code>Plugins.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0018-wasm-plugins.md" target="_blank" rel="noreferrer">0018</a></td><td>Wasm 插件 ABI（Experimental）：同一套消息经导出函数 + 线性内存</td><td>规范 <code>plugin/wasm.md</code>；参考实现 <code>Plugins.Wasm</code>，套件 <code>Plugins.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0019-remote-providers.md" target="_blank" rel="noreferrer">0019</a></td><td>远程 Provider：子系统能力经插件操作提供，首个操作集 <code>caching.distributed@1</code></td><td>规范 <code>provider/</code>；适配器 <code>Caching.Remote</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0020-migration.md" target="_blank" rel="noreferrer">0020</a></td><td>版本迁移：<code>xihan migrate &lt;来源版本&gt;</code> 按规则集做语法级重写，不做运行期兼容桥</td><td>规范 <code>migration/README.md</code>；实现 <code>XiHan.Framework.Cli</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0021-workflow.md" target="_blank" rel="noreferrer">0021</a></td><td>工作流：持久化执行</td><td>2026-10-26 修订：触发式启动、事件网关、外部任务、HTTP 与补偿活动、跳转与迁移、认领 / 退回 / 催办、提醒与审批阈值、保留期清理；参考实现 <code>Workflow.Abstractions</code>、<code>Workflow.InMemory</code>、<code>Workflow.Database</code>，套件 <code>Workflow.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0022-ai.md" target="_blank" rel="noreferrer">0022</a></td><td>AI：聊天、嵌入、工具与知识</td><td>参考实现 <code>AI.Abstractions</code>、<code>AI.OpenAI</code>、<code>AI.VectorData</code>，套件 <code>AI.Conformance</code></td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0023-observability.md" target="_blank" rel="noreferrer">0023</a></td><td>可观测性：导出与运行信息</td><td>参考实现 <code>Observability.Abstractions</code>、<code>Observability.Host</code>、<code>Observability.OpenTelemetry</code>；运行信息不启动外部命令，取不到的项见正文</td></tr><tr><td><a href="https://github.com/XiHanFun/framework-spec/blob/main/rfcs/0024-versions-and-profiles.md" target="_blank" rel="noreferrer">0024</a></td><td>规范的版本与一致性档</td><td>档表 <code>conformance/profiles.json</code>，由 <code>tools/speccheck</code> 与 conformance 模块的测试核对；.NET 由架构测试 <code>SpecVectorCoverageTests</code> 按认领的档核对向量</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/getting-started/concepts">核心概念</a>：这些规范在 .NET 实现里对应什么</li><li><a href="/plugins/out-of-process">进程外插件</a>：用任意语言按规范写插件</li><li><a href="/appendix/contributing">贡献指南</a>：怎样提一个 RFC</li></ul>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};